use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() < 3 {
            continue
        }
        let from: int = parts[1].parse().unwrap_or(10)
        let to: int = parts[2].parse().unwrap_or(10)
        let mut v: int = 0
        for c in parts[0].chars() {
            let code = c as int
            let d: int = if code >= 65 { code - 55 } else { code - 48 }
            v = v * from + d
        }
        if v == 0 {
            println("0")
            continue
        }
        let mut out: Vec<char> = []
        while v > 0 {
            let r = (v % to) as usize
            out.push(digits.chars().nth(r).unwrap_or('0'))
            v = v / to
        }
        let mut s = ""
        let mut i = out.len() as int - 1
        while i >= 0 {
            s = s + out[i as usize].to_string()
            i -= 1
        }
        println("${s}")
    }
}

